<?php

namespace App\Support;

use App\Models\User;
use Closure;
use Illuminate\Database\UniqueConstraintViolationException;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;

/**
 * Idempotent financial writes (ARCHITECTURE §12). Contract:
 * - Header `Idempotency-Key`: 16–100 chars [A-Za-z0-9_-], generated by the client per intended operation.
 * - Scope: organization + user + operation; the hash covers the canonical payload and route target.
 * - The key is claimed inside the operation's transaction. Success stores status and body; a retry with the
 *   same key and payload replays them (header `Idempotent-Replayed: true`) without running the operation.
 * - Same key with a different payload: 409 IDEMPOTENCY_KEY_REUSED.
 * - Failed operations roll the claim back, so a retry re-evaluates. No TTL/expiry yet (TBD).
 */
class Idempotency
{
    public function __construct(private OrganizationContext $context) {}

    /** @param Closure(): array{0: int, 1: array} $operation returns [status, body]; runs inside the transaction. */
    public function run(Request $request, User $user, string $operation, array $payload, Closure $work): JsonResponse
    {
        $key = $request->header('Idempotency-Key');
        if (! is_string($key) || ! preg_match('/^[A-Za-z0-9_-]{16,100}$/', $key)) {
            throw ValidationException::withMessages(['idempotency_key' => ['Envie um cabeçalho Idempotency-Key válido para esta operação.']]);
        }
        $scope = [
            'organization_id' => $this->context->organization()->id,
            'user_id' => $user->id,
            'operation' => $operation,
            'idempotency_key' => $key,
        ];
        $hash = hash('sha256', json_encode([$operation, $payload], JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR));

        if ($replay = $this->replay($scope, $hash)) {
            return $replay;
        }

        try {
            return DB::transaction(function () use ($scope, $hash, $work) {
                // The unique index serializes requests with the same key: a concurrent one waits here and
                // then fails with a duplicate key, which is answered by replaying the committed result.
                $id = DB::table('idempotency_keys')->insertGetId([...$scope, 'request_hash' => $hash, 'created_at' => now('UTC'), 'updated_at' => now('UTC')]);
                [$status, $body] = $work();
                DB::table('idempotency_keys')->where('id', $id)->update([
                    'response_status' => $status,
                    'response_body' => json_encode($body, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR),
                    'updated_at' => now('UTC'),
                ]);

                return response()->json($body, $status);
            });
        } catch (UniqueConstraintViolationException $exception) {
            return $this->replay($scope, $hash) ?? throw $exception;
        }
    }

    private function replay(array $scope, string $hash): ?JsonResponse
    {
        $stored = DB::table('idempotency_keys')->where($scope)->first();
        if (! $stored) {
            return null;
        }
        if (! hash_equals($stored->request_hash, $hash)) {
            return $this->conflict('IDEMPOTENCY_KEY_REUSED', 'Esta chave já foi usada para outra operação. Gere uma nova tentativa.');
        }
        if ($stored->response_status === null) {
            return $this->conflict('IDEMPOTENCY_IN_PROGRESS', 'Esta operação ainda está sendo processada. Tente novamente em instantes.');
        }

        return response()->json(json_decode($stored->response_body, true), (int) $stored->response_status, ['Idempotent-Replayed' => 'true']);
    }

    private function conflict(string $code, string $message): JsonResponse
    {
        return response()->json(['message' => $message, 'code' => $code, 'errors' => (object) []], 409);
    }
}
